CREATE OR REPLACE FUNCTION public.save_treatment_revision(_patient_id uuid, _plan jsonb, _expected_at timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE p public.patients%ROWTYPE; revision uuid; BEGIN IF NOT public.has_role(auth.uid(), 'doctor'::public.app_role) THEN RAISE EXCEPTION '只有医生可以修改治疗方案'; END IF; IF jsonb_typeof(_plan) <> 'object' OR jsonb_typeof(_plan->'training') <> 'array' OR jsonb_typeof(_plan->'interventions') <> 'array' OR jsonb_array_length(_plan->'training') = 0 THEN RAISE EXCEPTION '方案必须包含具体训练和治疗类型'; END IF; SELECT * INTO p FROM public.patients WHERE id=_patient_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION '患者不存在'; END IF; IF p.ai_plan_at IS DISTINCT FROM _expected_at THEN RAISE EXCEPTION '方案已更新，请重新打开后编辑'; END IF; INSERT INTO public.treatment_plans(patient_id,plan,risk) VALUES(_patient_id,_plan,p.cognitive_risk) RETURNING id INTO revision; UPDATE public.patients SET ai_plan=_plan,ai_plan_at=clock_timestamp(),ai_plan_confirmed_at=NULL,ai_plan_confirmed_by=NULL WHERE id=_patient_id; RETURN revision; END $$; REVOKE ALL ON FUNCTION public.save_treatment_revision(uuid,jsonb,timestamptz) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.save_treatment_revision(uuid,jsonb,timestamptz) TO authenticated;